import osimport globimport randomimport numpy as npimport pandas as pdimport torchfrom PIL import Imagefrom abc import ABC, abstractmethodfrom torch.utils.data import Dataset, DataLoaderfrom .DataStructure import PhotoPaths, TimePoint, TimePointsfrom .util import replaceNone, _safe_floatdef getTimePointList(        tabular_path: str,        photo_path: str,        grade_type: str,        visit_lst: tuple = tuple(map(str, range(1, 10))),        center_lst: tuple = ('S01',),        min_grade: None | float = None,        max_grade: None | float = None) -> list:    """Parses tabular data and image directories to extract valid single time points."""    tabular_data = pd.read_excel(tabular_path)    prefix = photo_path.replace('*.jpg', '')    photo_lst = glob.glob(photo_path)  # Fetch all matching photo paths    # Extract filenames and filter based on valid visits and centers    photo_set = {os.path.split(photo)[-1] for photo in photo_lst}    filter_set = {photo for photo in photo_set if (photo[-7] in visit_lst and photo[: 3] in center_lst)}    timePoint_lst = []    for idx in range(len(tabular_data['SeriesID'])):        typeSeriesID = tabular_data['SeriesID'].iloc[idx]        patient_id = typeSeriesID[:6]        # Construct expected filenames for the four photo types        photo_D, photo_C = typeSeriesID + '_D.jpg', typeSeriesID + '_C.jpg'        photo_N, photo_P = typeSeriesID + '_N.jpg', typeSeriesID + '_P.jpg'        photoDCNP_set = {photo_D, photo_C, photo_N, photo_P}        # Construct full absolute paths        photopath_D, photopath_C = prefix + photo_D, prefix + photo_C        photopath_N, photopath_P = prefix + photo_N, prefix + photo_P        photopaths = PhotoPaths(photopath_D, photopath_C, photopath_N, photopath_P)        grade = _safe_float(tabular_data[grade_type].iloc[idx])        if grade is None:            continue        # Append to list if it meets the grade criteria and all 4 photos exist in the filtered set        if min_grade is not None and max_grade is not None:            if min_grade <= grade < max_grade and photoDCNP_set.issubset(filter_set):                timePoint = TimePoint(patient_id, photopaths, grade)                timePoint_lst.append(timePoint)        else:            if photoDCNP_set.issubset(filter_set):                timePoint = TimePoint(patient_id, photopaths, grade)                timePoint_lst.append(timePoint)    return timePoint_lstdef getTimePointsList(        tabular_path: str,        photo_path: str,        grade_type: str,        visit_lst: tuple = tuple(map(str, range(1, 10))),        center_lst: tuple = ('S01',)) -> list:    """Parses tabular data and aggregates individual time points into longitudinal sequences."""    tabular_data = pd.read_excel(tabular_path)    prefix = photo_path.replace('*.jpg', '')    photo_lst = glob.glob(photo_path)    photo_set = {os.path.split(photo)[-1] for photo in photo_lst}    filter_set = {photo for photo in photo_set if (photo[-7] in visit_lst and photo[: 3] in center_lst)}    timePoints_lst = []    # Identify unique longitudinal series prefixes    timeSeriesID_set = {photo[: 9] for photo in filter_set}    for timeSeriesID in timeSeriesID_set:        patient_id = timeSeriesID[:6]        times = {f'point_{i}': None for i in range(1, 10)}        for idx in range(len(tabular_data['SeriesID'])):            if tabular_data['SeriesID'].iloc[idx][: 9] == timeSeriesID:                typeSeriesID = tabular_data['SeriesID'].iloc[idx]                index = typeSeriesID[-1]  # Extract the specific visit index                photo_D, photo_C = typeSeriesID + '_D.jpg', typeSeriesID + '_C.jpg'                photo_N, photo_P = typeSeriesID + '_N.jpg', typeSeriesID + '_P.jpg'                photoDCNP_set = {photo_D, photo_C, photo_N, photo_P}                photopath_D, photopath_C = prefix + photo_D, prefix + photo_C                photopath_N, photopath_P = prefix + photo_N, prefix + photo_P                photopaths = PhotoPaths(photopath_D, photopath_C, photopath_N, photopath_P)                grade = _safe_float(tabular_data[grade_type].iloc[idx])                if grade is not None and photoDCNP_set.issubset(filter_set):                    timePoint = TimePoint(patient_id, photopaths, grade)                else:                    timePoint = None                times[f'point_{index}'] = timePoint        # Only keep series with at least 7 valid time points, and must include point_9        valid_points_count = sum(1 for i_time in times.values() if i_time is not None)        if valid_points_count > 6 and times['point_9'] is not None:            timePoints = TimePoints(patient_id, **times)            timePoints_lst.append(timePoints)    return timePoints_lstclass BaseDataset(Dataset, ABC):    """Abstract base class for PyTorch Datasets."""    def __init__(self, selector_lst: list, transform: list) -> None:        self.selector_lst = selector_lst        self.transform = transform    def __len__(self) -> int:        return len(self.selector_lst)    @abstractmethod    def __getitem__(self, idx: int) -> any:        passclass TimePointDataset(BaseDataset):    """Dataset for processing independent, single time points."""    def __getitem__(self, idx: int) -> tuple:        photoD = self.transform[0](Image.open(self.selector_lst[idx].photo_paths.photo_pathD))        photoC = self.transform[1](Image.open(self.selector_lst[idx].photo_paths.photo_pathC))        photoN = self.transform[2](Image.open(self.selector_lst[idx].photo_paths.photo_pathN))        photoP = self.transform[3](Image.open(self.selector_lst[idx].photo_paths.photo_pathP))        photos = torch.stack([photoD, photoC, photoN, photoP])        grade = torch.tensor(self.selector_lst[idx].grade)        return photos, gradeclass TimePointsDataset(BaseDataset):    """Dataset for processing longitudinal time point sequences."""    def __getitem__(self, idx: int) -> tuple:        photos_series = []        grade_series = []        for index in range(9):            selector = getattr(self.selector_lst[idx], f'point_{index + 1}')            if selector is not None:                photoD = self.transform[0](Image.open(selector.photo_paths.photo_pathD))                photoC = self.transform[1](Image.open(selector.photo_paths.photo_pathC))                photoN = self.transform[2](Image.open(selector.photo_paths.photo_pathN))                photoP = self.transform[3](Image.open(selector.photo_paths.photo_pathP))                photos = torch.stack([photoD, photoC, photoN, photoP])                grade = torch.tensor(selector.grade)            else:                photos = None                grade = None            photos_series.append(photos)            grade_series.append(grade)        # Impute missing values using the predefined replacement strategy        photos_series = torch.stack(replaceNone(photos_series))        grade_series = torch.stack(replaceNone(grade_series))        return photos_series, grade_seriesdef worker_init_fn(worker_id: int, seed: int = 42) -> None:    """Initializes each DataLoader worker with a unique, reproducible seed."""    worker_seed = seed + worker_id    np.random.seed(worker_seed)    random.seed(worker_seed)    torch.manual_seed(worker_seed)def getDataloader(        dataset: Dataset,        batch_size: int,        num_workers: int,        seed: int,        drop_last: bool,        shuffle: bool = True) -> DataLoader:    """Utility function to configure and generate a PyTorch DataLoader."""    generator = torch.Generator()    generator.manual_seed(seed)    dataloader_kwargs = dict(        dataset=dataset,        batch_size=batch_size,        num_workers=num_workers,        pin_memory=(num_workers > 0),        shuffle=shuffle,        drop_last=drop_last,        worker_init_fn=lambda worker_id: worker_init_fn(worker_id, seed),        generator=generator,    )    if num_workers > 0:        dataloader_kwargs.update(persistent_workers=True, prefetch_factor=4)    return DataLoader(**dataloader_kwargs)